import { cookies, headers } from 'next/headers';

export default function Home() {
  // Read theme cookie, default to 'light' if not set
  const theme = cookies().get('theme')?.value || 'light';

  // Read Accept-Language header, default to 'en' if not set
  const acceptLanguage = headers().get('accept-language');
  const preferredLanguage = acceptLanguage ? acceptLanguage.split(',')[0].split(';')[0] : 'en';

  return (
    <main style={{ padding: '2rem', maxWidth: '800px', margin: '0 auto' }}>
      <h1>User Preferences</h1>

      <div style={{ 
        backgroundColor: theme === 'dark' ? '#1a1a1a' : '#ffffff',
        color: theme === 'dark' ? '#ffffff' : '#000000',
        border: '1px solid #ccc',
        padding: '1.5rem',
        borderRadius: '8px',
        marginTop: '1rem'
      }}>
        <h2>Current Theme: {theme}</h2>
        <p>Preferred Language: {preferredLanguage}</p>

        <div style={{ marginTop: '1rem', fontSize: '0.9rem', color: '#666' }}>
          <p><strong>Note:</strong></p>
          <ul>
            <li>Theme: {theme === 'dark' ? 'Dark mode is active' : 'Light mode is active'}</li>
            <li>Language: Based on your browser's Accept-Language header</li>
          </ul>
        </div>
      </div>
    </main>
  );
}

